===== src/item-catalog.ts =====
     1	/** The insured things the MHPCO knows, and the price-list facts that both the
     2	 *  premium office and the claims office read off the same catalogue entry.
     3	 *  Neither side owns this knowledge: a new item type is one catalogue change,
     4	 *  not a change to how premiums or payouts are decided. */
     5	
     6	export interface Item {
     7	  type: string;
     8	  material?: string;
     9	  enchantment?: number;
    10	  cursed?: boolean;
    11	}
    12	
    13	/** One row of the MHPCO price list: everything the office has decided about an
    14	 *  item type. Insurance value and base premium are quoted together, per type,
    15	 *  and are revised together when the office reprices a type. */
    16	interface CatalogueEntry {
    17	  insuranceValue: number;
    18	  basePremium: number;
    19	}
    20	
    21	/** Every component -- rune, moonstone -- is insured for the same sum and
    22	 *  carries the same base premium, independent of which component it is. */
    23	const COMPONENT: CatalogueEntry = { insuranceValue: 250, basePremium: 25 };
    24	
    25	/** The MHPCO price list. Every item type the office recognizes appears here
    26	 *  exactly once, so a new type is one row, never two half-entries. */
    27	const PRICE_LIST: Record<string, CatalogueEntry> = {
    28	  sword: { insuranceValue: 1000, basePremium: 100 },
    29	  amulet: { insuranceValue: 600, basePremium: 60 },
    30	  staff: { insuranceValue: 800, basePremium: 80 },
    31	  potion: { insuranceValue: 400, basePremium: 40 },
    32	  rune: COMPONENT,
    33	  moonstone: COMPONENT,
    34	};
    35	
    36	/** The price list's entry for an insured item. */
    37	/** The MHPCO insures only what its price list names; anything else is refused. */
    38	function catalogueEntry(item: Item): CatalogueEntry {
    39	  const entry = PRICE_LIST[item.type];
    40	  if (entry === undefined) {
    41	    throw new Error(`the MHPCO price list knows no item of type "${item.type}"`);
    42	  }
    43	  return entry;
    44	}
    45	
    46	/** The sum the MHPCO insures an item for, per the price list. */
    47	export function insuranceValue(item: Item): number {
    48	  return catalogueEntry(item).insuranceValue;
    49	}
    50	
    51	/** The MHPCO price list's base premium for an insured item. */
    52	export function basePremium(item: Item): number {
    53	  return catalogueEntry(item).basePremium;
    54	}
    55	
    56	/** Two items are "alike" when they share this key. The MHPCO reads "alike"
    57	 *  as *the same type* -- a rune is alike another rune, but not a moonstone. */
    58	export function alikeKey(item: Item): string {
    59	  return item.type;
    60	}
===== src/rounding.ts =====
     1	/** How the MHPCO resolves a fraction of a G.
     2	 *
     3	 *  The office's tradition is one rule, not two: *every fraction falls in the
     4	 *  MHPCO's favour*. What favours the office depends on which way the money is
     5	 *  moving -- a fraction of a premium it collects is rounded up, a fraction of a
     6	 *  payout it pays is rounded down -- but the decision behind both is the same
     7	 *  one, and the office would revise it in one act. Keeping the two directions
     8	 *  side by side here is what lets the asymmetry be read as deliberate rather
     9	 *  than met twice, as an accident, in the tariff and in the handbook. */
    10	
    11	/** An amount the customer owes the MHPCO, rounded to the whole G in the
    12	 *  office's favour: upwards. */
    13	export function amountCollectedInMHPCOsFavour(amount: number): number {
    14	  return Math.ceil(amount);
    15	}
    16	
    17	/** An amount the MHPCO owes the customer, rounded to the whole G in the
    18	 *  office's favour: downwards. */
    19	export function amountPaidInMHPCOsFavour(amount: number): number {
    20	  return Math.floor(amount);
    21	}
===== src/premium.ts =====
     1	/** The premium office: what the MHPCO charges to take a list of items on risk.
     2	 *  Every decision here belongs to the tariff -- the price list, the building
     3	 *  block, the risk surcharges, the customer's standing, the processing fee, and
     4	 *  the rounding that falls the office's way. It changes when the tariff is
     5	 *  revised, independently of how claims are settled. */
     6	
     7	import { alikeKey, basePremium, type Item } from "./item-catalog.js";
     8	import { amountCollectedInMHPCOsFavour } from "./rounding.js";
     9	
    10	export interface Customer {
    11	  yearsWithMHPCO: number;
    12	}
    13	
    14	/** The MHPCO price list offers a building block of 3 alike items at a
    15	 *  special base premium instead of the sum of the per-item prices. The
    16	 *  price list states the rule for components; the office has not yet ruled
    17	 *  on whether a block of 3 alike main items is granted the same price. */
    18	const BUILDING_BLOCK_SIZE = 3;
    19	const BUILDING_BLOCK_BASE_PREMIUM = 60;
    20	
    21	const CURSE_SURCHARGE_RATE = 0.5;
    22	const HIGH_ENCHANTMENT_THRESHOLD = 5;
    23	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    24	const LOYALTY_YEARS_THRESHOLD = 2;
    25	const LOYALTY_DISCOUNT_RATE = 0.2;
    26	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    28	const PROCESSING_FEE = 5;
    29	
    30	/** Whether a group of alike items qualifies for the special building-block
    31	 *  price. The MHPCO grants the block only for a group of exactly 3 -- a
    32	 *  fourth alike item forfeits the special price for the whole group. */
    33	function formsBuildingBlock(alikeItems: Item[]): boolean {
    34	  return alikeItems.length === BUILDING_BLOCK_SIZE;
    35	}
    36	
    37	/** The base premium the price list charges for one group of alike items:
    38	 *  the special block price when the group forms a building block, otherwise
    39	 *  the per-item price of every item in the group. */
    40	function alikeGroupBasePremium(alikeItems: Item[]): number {
    41	  if (formsBuildingBlock(alikeItems)) {
    42	    return BUILDING_BLOCK_BASE_PREMIUM;
    43	  }
    44	  return alikeItems.reduce((sum, item) => sum + basePremium(item), 0);
    45	}
    46	
    47	/** The items of a quote, partitioned into groups of alike items. */
    48	function groupAlikeItems(items: Item[]): Item[][] {
    49	  const groups = new Map<string, Item[]>();
    50	  for (const item of items) {
    51	    const key = alikeKey(item);
    52	    const alike = groups.get(key) ?? [];
    53	    alike.push(item);
    54	    groups.set(key, alike);
    55	  }
    56	  return [...groups.values()];
    57	}
    58	
    59	/** The policy base premium: the sum of the base premiums of all insured
    60	 *  items, before any modifier. */
    61	function policyBasePremium(items: Item[]): number {
    62	  return groupAlikeItems(items).reduce(
    63	    (sum, alikeGroup) => sum + alikeGroupBasePremium(alikeGroup),
    64	    0,
    65	  );
    66	}
    67	
    68	/** A cursed item carries a risk surcharge for that item alone, not for the
    69	 *  policy. */
    70	function isCursed(item: Item): boolean {
    71	  return item.cursed === true;
    72	}
    73	
    74	/** An item counts as highly enchanted from enchantment level 5 upwards. */
    75	function isHighlyEnchanted(item: Item): boolean {
    76	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
    77	}
    78	
    79	/** The risk surcharges an item carries on its own base premium. An item may
    80	 *  carry several risks at once, and the MHPCO charges every one of them in
    81	 *  full: the surcharges accumulate, each measured on the item's *unmodified*
    82	 *  base premium, so a cursed and highly enchanted sword pays 50 % + 30 %. */
    83	function itemRiskSurcharge(item: Item): number {
    84	  const base = basePremium(item);
    85	  const curse = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
    86	  const enchantment = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
    87	  return curse + enchantment;
    88	}
    89	
    90	/** The risk surcharges of all insured items. */
    91	function policyRiskSurcharge(items: Item[]): number {
    92	  return items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
    93	}
    94	
    95	/** How the customer stands with the MHPCO at the moment of this quote: the
    96	 *  length of the business relationship and the number of contracts that
    97	 *  precede this one in the customer's scenario. The policy-wide discounts are
    98	 *  decisions about this standing, not about the insured items. */
    99	export interface CustomerStanding {
   100	  customer: Customer;
   101	  previousContracts: number;
   102	}
   103	
   104	/** A customer is long-standing from 2 years of business with the MHPCO. */
   105	function isLongStanding(standing: CustomerStanding): boolean {
   106	  return standing.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
   107	}
   108	
   109	/** Every contract after the customer's first earns the follow-up discount. */
   110	function isFollowUpContract(standing: CustomerStanding): boolean {
   111	  return standing.previousContracts >= 1;
   112	}
   113	
   114	/** The net policy-wide modifier, which the MHPCO charges against the
   115	 *  *unmodified* policy base premium -- item risk surcharges do not raise the
   116	 *  amount these modifiers are measured on. All three policy-wide modifiers are
   117	 *  measured on that same base and accumulated here: the initial assessment
   118	 *  surcharge, the loyalty discount, and the follow-up contract discount. Every
   119	 *  quote is treated as a first insurance and carries the initial assessment
   120	 *  surcharge, regardless of customer history -- so a long-standing customer's
   121	 *  follow-up contract for a new item carries both the surcharge and both
   122	 *  discounts. */
   123	function policyModifierAdjustment(policyBase: number, standing: CustomerStanding): number {
   124	  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
   125	  const loyalty = isLongStanding(standing) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
   126	  const followUp = isFollowUpContract(standing)
   127	    ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
   128	    : 0;
   129	  return firstInsurance - loyalty - followUp;
   130	}
   131	
   132	/** The policy premium with all modifiers applied, before the processing fee:
   133	 *  the price-list base premium, plus the risk surcharges the individual items
   134	 *  carry, plus the policy-wide modifiers. */
   135	function modifiedPolicyPremium(items: Item[], standing: CustomerStanding): number {
   136	  const policyBase = policyBasePremium(items);
   137	  return (
   138	    policyBase + policyRiskSurcharge(items) + policyModifierAdjustment(policyBase, standing)
   139	  );
   140	}
   141	
   142	/** The settlement the MHPCO bills for a premium it has calculated: the office
   143	 *  adds its processing fee to every premium, last of all and after every
   144	 *  modifier, and then bills the whole G in its own favour. What the
   145	 *  office charges on top of the calculated risk changes independently of how
   146	 *  the premium itself was arrived at; in whose favour the fraction falls is the
   147	 *  office's own tradition, kept in one place for both counters. */
   148	function settledPremium(modifiedPremium: number): number {
   149	  return amountCollectedInMHPCOsFavour(modifiedPremium + PROCESSING_FEE);
   150	}
   151	
   152	/** The premium the MHPCO charges a customer for insuring a list of items:
   153	 *  the modified policy premium, settled by the office. */
   154	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
   155	  return settledPremium(modifiedPolicyPremium(items, { customer, previousContracts }));
   156	}
